package pe.edu.cacaoselva.desktop.controller;
import javafx.application.Platform; import pe.edu.cacaoselva.application.port.LoteQueryPort; import pe.edu.cacaoselva.desktop.view.LoteView; import java.util.concurrent.CompletableFuture;
public class LoteDesktopController { private final LoteView view; private final LoteQueryPort queryPort; public LoteDesktopController(LoteView view,LoteQueryPort queryPort){this.view=view;this.queryPort=queryPort;view.getConsultarButton().setOnAction(e->consultarLotes());} private void consultarLotes(){view.mostrarEstado("Consultando..."); CompletableFuture.supplyAsync(queryPort::obtenerLotes).thenAccept(lotes->Platform.runLater(()->{view.mostrarLotes(lotes);view.mostrarEstado(lotes.size()+" lotes recibidos");})).exceptionally(error->{Platform.runLater(()->view.mostrarEstado("No se pudo conectar con la API"));return null;});} }
